practice.solution:
def powers_of_two():
    power = 1
    while True:
        yield power
        power *= 2


def count_up(n):
    for i in range(1, n + 1):
        yield i


def countdown(n):
    while n > 0:
        yield n
        n -= 1


def up_and_down(n):
    yield from count_up(n)
    yield from countdown(n)


for power in powers_of_two():
    if power > 1000:
        print(f"First above 1000: {power}")
        break

print(list(up_and_down(3)))
